def git(repo, *args, data=None, check=True):
    p = subprocess.run(['git', '-C', str(repo), *args], input=data,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if check and p.returncode:
        raise RuntimeError(p.stderr.decode('utf-8', 'replace').strip()
                           or 'git failed: ' + ' '.join(args))
    return p


def plain(path):
    """Reject symlink components; do not traverse another tree accidentally."""
    for item in (path, *path.parents):
        if item.is_symlink():
            raise RuntimeError('Symlink wird nicht verwendet: ' + str(item))
    return path


def relpath(text):
    p = PurePosixPath(text)
    if (not p.parts or p.is_absolute() or '..' in p.parts
            or any(c in text for c in '\\\t\r\n\x00')):
        raise RuntimeError('Ungueltiger relativer Pfad: ' + repr(text))
    return p


def result_path(p):
    return p.suffix.lower() in SAFE_SUFFIXES or p.name in SAFE_ENV_FILES


def read_stable(path):
    plain(path)
    before = path.stat()
    if not stat.S_ISREG(before.st_mode):
        raise RuntimeError('Keine regulaere Quelldatei: ' + str(path))
    if before.st_size > MAX_FILE:
        raise RuntimeError('Einzeldatei ueber 32 MiB; nicht kopiert: ' + str(path))
    raw = path.read_bytes()
    after = path.stat()
    fields = lambda s: (s.st_dev, s.st_ino, s.st_size, s.st_mtime_ns)
    if fields(before) != fields(after) or len(raw) != before.st_size:
        raise RuntimeError('Quelle aendert sich noch; nicht kopiert: ' + str(path))
    return raw


class LocalSources:
    def __init__(self, home, downloads):
        self.home, self.downloads = home, downloads
        self.archives = {}

    def resolve(self, source, member):
        """Return original bytes and local provenance, never extract a tree."""
        if not source.endswith('.zip'):
            p = self.downloads / source
            if p.is_file():
                return read_stable(p), str(p)
            return None, str(p)
        stem = re.sub(r'\(\d+\)$', '', source[:-4])
        roots = []
        if stem.endswith('_debug_pack'):
            run = stem[:-len('_debug_pack')]
            roots.append(self.home / 'Models/EvaluationRuns' / run)
        roots += [self.downloads / stem, self.downloads / source[:-4]]
        variants = [member]
        first, sep, remainder = member.partition('/')
        if sep and first in {'v27930_audit', stem}:
            variants.append(remainder)
        for root in dict.fromkeys(roots):
            for relative in variants:
                p = root / relpath(relative)
                if p.is_file():
                    return read_stable(p), str(p)
        archives = [self.downloads / source, self.downloads / (stem + '.zip')]
        # A '(1)' or '(5)' download suffix does not change member identity.
        archives += sorted(self.downloads.glob(stem + '([0-9]*).zip'))
        for path in dict.fromkeys(archives):
            if not path.is_file():
                continue
            plain(path)
            if path not in self.archives:
                self.archives[path] = zipfile.ZipFile(path)
            z = self.archives[path]
            names = [member, stem + '/' + member, source[:-4] + '/' + member]
            for name in dict.fromkeys(names):
                infos = [i for i in z.infolist() if i.filename == name]
                if len(infos) > 1:
                    raise RuntimeError('Doppeltes ZIP-Mitglied: ' + str(path) + ':' + name)
                if not infos:
                    continue
                info = infos[0]
                relpath(name)
                if stat.S_ISLNK(info.external_attr >> 16) or info.is_dir():
                    raise RuntimeError('Ungueltiges ZIP-Mitglied: ' + name)
                if info.file_size > MAX_FILE:
                    raise RuntimeError('ZIP-Ergebnisdatei ueber 32 MiB: ' + name)
                return z.read(info), str(path) + '::' + name
        return None, str(roots[0]) + '/' + member

    def close(self):
        for z in self.archives.values():
            z.close()


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--repo', type=Path, default=Path.home() / 'onnx-splitpoint-results')
    ap.add_argument('--home', type=Path, default=Path.home(), help='Lokale Quelldateien, normalerweise $HOME')
    ap.add_argument('--downloads', type=Path)
    ap.add_argument('--push', action='store_true', help='Nach Pruefung mit PUSH bestaetigen, committen und pushen')
    args = ap.parse_args()
    repo, home = args.repo.expanduser().absolute(), args.home.expanduser().absolute()
    downloads = (args.downloads or home / 'Downloads').expanduser().absolute()
    plain(repo)
    if git(repo, 'rev-parse', '--show-toplevel').stdout.decode().strip() != str(repo):
        raise RuntimeError('Kein eigenes Repository an diesem Pfad: ' + str(repo))
    if not (repo / 'scripts/check_before_commit.py').is_file():
        raise RuntimeError('Vorhandenes scripts/check_before_commit.py fehlt')
    if git(repo, 'diff', '--cached', '--name-only', '-z').stdout:
        raise RuntimeError('Bereits vorgemerkte Aenderungen vorhanden. Erst separat committen oder pruefen; nichts veraendert.')
    branch = git(repo, 'symbolic-ref', '--quiet', '--short', 'HEAD').stdout.decode().strip()
    urls = git(repo, 'remote', 'get-url', '--push', '--all', 'origin').stdout.decode().splitlines()
    allowed = {'https://github.com/Keff789/onnx-splitpoint-results',
               'https://github.com/Keff789/onnx-splitpoint-results.git',
               'git@github.com:Keff789/onnx-splitpoint-results.git',
               'git@github.com:Keff789/onnx-splitpoint-results',
               'ssh://git@github.com/Keff789/onnx-splitpoint-results.git'}
    if len(urls) != 1 or urls[0] not in allowed:
        raise RuntimeError('Push-Remote ist nicht eindeutig das erwartete Repository; nichts veraendert.')
    mirror = git(repo, 'config', '--bool', '--get', 'remote.origin.mirror', check=False)
    if mirror.stdout.strip() == b'true':
        raise RuntimeError('Mirror-Remote wird nicht verwendet')

    sources = LocalSources(home, downloads)
    selected, notes, missing_required = {}, [], []
    total = 0
    try:
        for source, entries in SELECTION['sources'].items():
            found = 0
            for member, destination in entries:
                dest = relpath(destination)
                if not result_path(dest) or (member and not result_path(relpath(member))):
                    raise RuntimeError('Nicht erlaubter Dateityp in Auswahl: ' + destination)
                raw, actual = sources.resolve(source, member)
                if raw is None:
                    notes.append(('MISSING', actual, destination, 0))
                    if member in REQUIRED.get(source, []):
                        missing_required.append(actual)
                    continue
                # Text-only results, no renamed model binaries or tensor archives.
                raw.decode('utf-8-sig')
                if b'\x00' in raw:
                    raise RuntimeError('Binaerinhalt in Textdatei: ' + actual)
                if destination in selected and selected[destination] != raw:
                    raise RuntimeError('Verschiedene Quellen fuer: ' + destination)
                selected[destination] = raw
                notes.append(('PRESENT', actual, destination, len(raw)))
                found += 1
            print(f'SOURCE={source} RESULTS={found}/{len(entries)}', flush=True)
        for c in SELECTION['calibrations']:
            path = home / relpath(c['home_relative_path'])
            destination = c['destination']
            if not path.is_file():
                notes.append(('MISSING', str(path), destination, 0))
                continue
            raw = read_stable(path)
            json.loads(raw)
            expected = c['expected_sha256_from_result']
            if expected and hashlib.sha256(raw).hexdigest() != expected:
                notes.append(('BOUND_HASH_MISMATCH_NOT_COPIED', str(path), destination, len(raw)))
                continue
            selected[destination] = raw
            notes.append(('PRESENT', str(path), destination, len(raw)))
    finally:
        sources.close()
    if missing_required:
        raise RuntimeError('Kernevidence fehlt; noch nichts kopiert:\n' + '\n'.join(missing_required))
    gaps = [n for n in notes if n[0] != 'PRESENT']
    inv = 'inventory/evidence_direct_20260908.tsv'
    selected[inv] = ('status\tsource\tdestination\tbytes\n' + ''.join(
        f'{status}\t{source}\t{dest}\t{size}\n' for status, source, dest, size in notes
    )).encode()
    readme = 'docs/EVIDENCE_DIRECT_2026-09-08.md'
    selected[readme] = (
        '# Lokal gesicherte Ergebnisse vom 8. September 2026\n\n'
        'Quelle: bestehende Dateien auf Smartmirror2, bevorzugt Laufordner; '
        'ersatzweise einzelne Mitglieder bereits lokal vorhandener Evidence-ZIPs.\n\n'
        'Nur Ergebnisdateien, Protokolle, Profile, Vertragsmetadaten und bereits '
        'vorhandene Dokumente. Keine Modelle, Gewichte, HEFs, DXNNs, Engines, '
        'Bilder, NPY/NPZ/BIN-Tensoren oder kompletten Archive. R2-Buildmetadaten '
        'liegen wegen der bestehenden Git-Ignoreregel fuer build/ unter build_metadata/. '
        'Die Dateiinhalte selbst sind unveraendert.\n\n'
        'R1/R2 bleiben diagnostisch, MobileNet-B500 nach Mean/Std bleibt offen. '
        'Das Complete Set complete_set_20260907_161614 bleibt historisch failed. '
        'Die v30-Teilabnahme und die Installations-/Hardwarebefunde sind getrennt; '
        'der v31-Plan ist keine Ausfuehrungsevidence.\n\n'
        f'Quellenstatus und fehlende Dateien: ../{inv}. '
        f'Offene optionale Quelldateien: {len(gaps)}. '
        'Nicht lokal vorhandene Chat-Auswertungen oder Abnahme-ZIPs werden nicht '
        'rekonstruiert. Der neuere Overnight-Lauf vom 08.09. wird nicht gesammelt.\n'
    ).encode()
    script_rel = 'scripts/collect_evidence_20260908_direct.py'
    selected[script_rel] = Path(__file__).read_bytes()
    total = sum(len(b) for b in selected.values())
    if total > MAX_TOTAL:
        raise RuntimeError('Auswahl ueber 256 MiB; nichts kopiert')
    generated = {inv, readme}
    new_count, same_count = 0, 0
    # Check ALL destinations first, so known conflicts cannot partially overwrite a run.
    for relative, raw in selected.items():
        path = repo / relpath(relative)
        plain(path)
        if path.exists():
            old = path.read_bytes()
            if old != raw and relative not in generated:
                raise RuntimeError('Vorhandene Datei weicht ab; nichts ueberschrieben: ' + relative)
            if old == raw:
                same_count += 1
        else:
            new_count += 1
    for relative, raw in selected.items():
        path = repo / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        if path.exists():
            if relative in generated and path.read_bytes() != raw:
                path.write_bytes(raw)
        else:
            with path.open('xb') as f:
                f.write(raw)
    work = repo / '.collection-work'
    plain(work)
    work.mkdir(exist_ok=True)
    check = subprocess.run([sys.executable, '-I', '-B',
        str(repo / 'scripts/check_before_commit.py'), str(repo)], capture_output=True)
    checklog = work / 'evidence_direct_20260908_precommit.log'
    checklog.write_bytes(check.stdout + check.stderr)
    print(f'COLLECTED_FILES={len(selected)} NEW={new_count} IDENTICAL={same_count} MiB={total/1048576:.2f}')
    print(f'OPTIONAL_MISSING_OR_DIFFERENT={len(gaps)}; DETAILS={repo / inv}')
    print(f'PRECOMMIT_LOG={checklog}')
    for line in check.stdout.decode('utf-8', 'replace').splitlines():
        if line.startswith(('fatal=', 'RESULT=', 'ERROR ')):
            print(line)
    if check.returncode:
        raise RuntimeError('Vorhandener Precommit-Check fehlgeschlagen; keine Dateien vorgemerkt')
    # No git add . / -A: only this run's explicit, safe selection is staged.
    paths = b''.join(p.encode() + b'\0' for p in sorted(selected))
    git(repo, '--literal-pathspecs', 'add', '--pathspec-from-file=-',
        '--pathspec-file-nul', data=paths)
    staged = git(repo, 'diff', '--cached', '--name-only', '-z').stdout
    permitted = set(selected)
    if any(p.decode() not in permitted for p in staged.split(b'\0') if p):
        raise RuntimeError('Weitere Dateien im Index; kein automatischer Commit/Push')
    print(git(repo, 'diff', '--cached', '--stat').stdout.decode(), end='')
    print(f'PUSH_TARGET=origin branch={branch}')
    if not args.push:
        print('STAGED_FOR_REVIEW=YES; COMMIT_AND_PUSH=NOT_RUN')
        return 0
    if not staged:
        print('NO_NEW_STAGED_RESULTS; no commit or push performed')
        return 0
    print('\nDie Protokolle koennen interne IPs/Pfade enthalten. Den obigen Diff und '
          'den Precommit-Log pruefen. Nur der aktuelle Index wird committed; ein '
          'Push uebertraegt auch bereits vorhandene ungesendete Commits dieser Branch.')
    answer = input('Zum Commit und Push exakt PUSH eingeben (sonst bleiben Dateien nur vorgemerkt): ').strip()
    if answer != 'PUSH':
        print('PUSH=NOT_REQUESTED; Ergebnisse sind lokal vorgemerkt')
        return 0
    # Recheck the staged names and destination immediately before publishing.
    if git(repo, 'diff', '--cached', '--name-only', '-z').stdout != staged:
        raise RuntimeError('Index zwischenzeitlich veraendert; kein Commit/Push')
    if git(repo, 'remote', 'get-url', '--push', '--all', 'origin').stdout.decode().splitlines() != urls:
        raise RuntimeError('Remote zwischenzeitlich veraendert; kein Commit/Push')
    commit = git(repo, 'commit', '-m', 'Archive local DeepX R1-R2 and v29-v30 result evidence')
    print(commit.stdout.decode('utf-8', 'replace'))
    # Explicit current-branch refspec, no forced updates and no tag propagation.
    p = subprocess.run(['git', '-C', str(repo), 'push', '--no-follow-tags',
                        'origin', f'HEAD:refs/heads/{branch}'])
    if p.returncode:
        print('PUSH=FAILED; lokaler Commit bleibt erhalten. Kein Reset/Force-Push ausgefuehrt.')
        return p.returncode
    print('PUSH=PASS')
    return 0


if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except (Exception, KeyboardInterrupt) as exc:
        print('STOP: ' + str(exc), file=sys.stderr)
        raise SystemExit(2)
